// Decode multi-frame zstd session logs and grep for 监测范围 / banner keywords
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const dir = process.argv[2];
const keyword = process.argv[3] || '监测范围';
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);

function decompressFrames(buf) {
  const parts = [];
  let start = 0;
  while (start < buf.length) {
    const idx = buf.indexOf(MAGIC, start);
    if (idx < 0) break;
    let end = buf.indexOf(MAGIC, idx + 4);
    if (end < 0) end = buf.length;
    try {
      parts.push(zlib.zstdDecompressSync(buf.subarray(idx, end)));
    } catch (e) { /* skip bad frame */ }
    start = end;
  }
  return Buffer.concat(parts).toString('utf8');
}

const files = fs.readdirSync(dir).filter(f => f.endsWith('.zstd'));
for (const f of files) {
  const full = path.join(dir, f);
  let text;
  try { text = decompressFrames(fs.readFileSync(full)); } catch (e) { continue; }
  if (!text) continue;
  const lines = text.split('\n');
  let hits = 0;
  for (const line of lines) {
    if (line.includes(keyword)) {
      hits++;
      // print shortened context
      const i = line.indexOf(keyword);
      console.log(`[${f}] ...${line.slice(Math.max(0, i - 120), i + 160)}...`);
      if (hits >= 4) break;
    }
  }
}

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const root = 'C:/Users/Administrator/.dsh/sessions';
const keyword = process.argv[2] || '监测范围';
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function decompressFrames(buf) {
  const parts = []; let start = 0;
  while (start < buf.length) {
    const idx = buf.indexOf(MAGIC, start);
    if (idx < 0) break;
    let end = buf.indexOf(MAGIC, idx + 4);
    if (end < 0) end = buf.length;
    try { parts.push(zlib.zstdDecompressSync(buf.subarray(idx, end))); } catch (e) {}
    start = end;
  }
  return Buffer.concat(parts).toString('utf8');
}
const ws = fs.readdirSync(root).filter(d => fs.statSync(path.join(root, d)).isDirectory());
for (const w of ws) {
  const wdir = path.join(root, w);
  const sessions = fs.readdirSync(wdir).filter(d => fs.statSync(path.join(wdir, d)).isDirectory());
  for (const s of sessions) {
    const f = path.join(wdir, s, 'session.v4.jsonl.zstd');
    if (!fs.existsSync(f)) continue;
    let text; try { text = decompressFrames(fs.readFileSync(f)); } catch (e) { continue; }
    if (!text || !text.includes(keyword)) continue;
    const lines = text.split('\n');
    let shown = 0;
    for (const line of lines) {
      if (!line.includes(keyword)) continue;
      // try to isolate role+text
      let txt = line;
      try {
        const o = JSON.parse(line);
        txt = JSON.stringify(o).slice(0, 4000);
      } catch (e) {}
      const i = txt.indexOf(keyword);
      console.log(`### ${w} :: ${s}`);
      console.log('   ' + txt.slice(Math.max(0, i - 200), i + 260).replace(/\s+/g, ' '));
      shown++;
      if (shown >= 3) break;
    }
  }
}

// Dump the user turns of a session mentioning a keyword, plus following assistant text,
// to understand the historical conversation.
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const root = 'C:/Users/Administrator/.dsh/sessions';
const wsName = process.argv[2];
const sess = process.argv[3];
const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function decompressFrames(buf) {
  const parts = []; let start = 0;
  while (start < buf.length) {
    const idx = buf.indexOf(MAGIC, start);
    if (idx < 0) break;
    let end = buf.indexOf(MAGIC, idx + 4);
    if (end < 0) end = buf.length;
    try { parts.push(zlib.zstdDecompressSync(buf.subarray(idx, end))); } catch (e) {}
    start = end;
  }
  return Buffer.concat(parts).toString('utf8');
}
const f = path.join(root, wsName, sess, 'session.v4.jsonl.zstd');
const text = decompressFrames(fs.readFileSync(f));
const lines = text.split('\n').filter(Boolean);
for (const line of lines) {
  let o; try { o = JSON.parse(line); } catch { continue; }
  const t = o.type;
  if (t === 'user/message' || t === 'assistant/message' || t === 'session/title') {
    let txt = '';
    const d = o.data || {};
    if (d.content) {
      for (const c of d.content) { if (c.text) txt += c.text; }
    }
    if (d.title) txt = '[TITLE] ' + d.title;
    if (txt) console.log(`\n===== ${t} seq=${o.seq} =====\n` + txt.slice(0, 2500));
  }
}

